-- ============================================================================
-- TaskEarn × Supabase — OPTIONAL media data seed (logos + banner images)
-- ============================================================================
-- WHAT THIS IS: the admin-uploaded images from the current working deployment
-- (payout-channel logos, payment-method logos, site branding images and the
-- team-salary banner), exported as plain SQL so they can be copied to another
-- Supabase project WITHOUT re-uploading every file through the Admin Panel.
--
-- THIS FILE IS OPTIONAL. The schema does not need it: every logo_url column
-- and image setting already exists, and the Admin Panel (Payment Methods /
-- Withdrawal Methods / Branding / Home Settings) can upload/replace/remove
-- all of these images at any time. Only run this if you want THIS EXACT set
-- of images on the target database.
--
-- CAUTION: these statements OVERWRITE the current logo/image values on the
-- target database (rows matched by name / setting key). If the target's
-- admin has already uploaded their own logos, do NOT run this file.
--
-- Images are stored as data URLs (data:image/png;base64,...) inside the
-- existing logo_url columns / system_settings values — the project uses NO
-- Supabase Storage buckets by design.
-- ============================================================================

-- 1. Payout channel logos (Withdraw page dropdown channels)
update public.withdrawal_methods set logo_url = 'data:image/jpeg;base64,', updated_at = now() where name = 'EasyPaisa';
update public.withdrawal_methods set logo_url = 'data:image/jpeg;base64,', updated_at = now() where name = 'JazzCash';
update public.withdrawal_methods set logo_url = 'data:image/png;base64,', updated_at = now() where name = 'UPaisa';
update public.withdrawal_methods set logo_url = 'data:image/png;base64,', updated_at = now() where name = 'SadaPay';
update public.withdrawal_methods set logo_url = 'data:image/png;base64,', updated_at = now() where name = 'NayaPay';
update public.withdrawal_methods set logo_url = 'data:image/png;base64,', updated_at = now() where name = 'UBL Bank';
update public.withdrawal_methods set logo_url = 'data:image/png;base64,', updated_at = now() where name = 'Bank Al Habib';

-- 2. Deposit/checkout payment method logos
update public.payment_methods set logo_url = 'data:image/jpeg;base64,', updated_at = now() where name = 'EasyPaisa';
update public.payment_methods set logo_url = 'data:image/jpeg;base64,', updated_at = now() where name = 'JazzCash';
update public.payment_methods set logo_url = 'data:image/jpeg;base64,', updated_at = now() where name = 'USDT (TRC20)';

-- 3. Branding / media-slot images (system_settings)
insert into public.system_settings (key, value) values ('site_logo_url', 'data:image/jpeg;base64,') on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.system_settings (key, value) values ('site_favicon_url', 'data:image/jpeg;base64,') on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.system_settings (key, value) values ('wallet_method_image_url', 'data:image/png;base64,') on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.system_settings (key, value) values ('home_team_salary_image', 'data:image/png;base64,') on conflict (key) do update set value = excluded.value, updated_at = now();
-- (setting 'home_welcome_popup_image' is empty in the source deployment — skipped)
